import{I as e,o as p,c as t,b6 as l,J as o,w as h,j as a,a as r}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법","description":"제로 베이스 독자를 위한 The Mom Test 입문 글입니다. 예의상 긍정 피드백을 피하고, 실제 행동, 구체적 사실, 이미 존재하는 문제를 중심으로 사용자 인터뷰를 진행해 \\"듣기에는 좋다\\"를 더 신뢰할 수 있는 수요 판단으로 바꾸는 법을 배웁니다.","frontmatter":{"title":"The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법","description":"제로 베이스 독자를 위한 The Mom Test 입문 글입니다. 예의상 긍정 피드백을 피하고, 실제 행동, 구체적 사실, 이미 존재하는 문제를 중심으로 사용자 인터뷰를 진행해 \\"듣기에는 좋다\\"를 더 신뢰할 수 있는 수요 판단으로 바꾸는 법을 배웁니다."},"headers":[],"relativePath":"ko-kr/stage-1/appendix-mom-test/index.md","filePath":"ko-kr/stage-1/appendix-mom-test/index.md"}'),d={name:"ko-kr/stage-1/appendix-mom-test/index.md"},m=Object.assign(d,{setup(c){const n="약 <strong>1.5시간</strong>";return(u,s)=>{const i=e("ChapterIntroduction");return p(),t("div",null,[s[1]||(s[1]=l('<h1 id="the-mom-test-사용자-인터뷰로-수요를-검증하는-방법" tabindex="-1">The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법 <a class="header-anchor" href="#the-mom-test-사용자-인터뷰로-수요를-검증하는-방법" aria-label="Permalink to “The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법”">​</a></h1><p><a id="top-mom"></a></p><h2 id="이-장의-가이드" tabindex="-1">이 장의 가이드 <a class="header-anchor" href="#이-장의-가이드" aria-label="Permalink to “이 장의 가이드”">​</a></h2>',3)),o(i,{duration:n,tags:["사용자 인터뷰","수요 검증","사용자 조사","제품 조사"],coreOutput:"실제 정보를 더 잘 끌어낼 수 있는 인터뷰 질문 세트 1개",expectedOutput:"사용자의 예의상 응원을 검증으로 받아들이지 않고, 실제 행동으로 방향을 판단하게 됩니다"},{default:h(()=>[...s[0]||(s[0]=[a("p",null,'많은 사람이 처음 제품 조사를 할 때, 가장 중요한 것이 "누군가와 이야기하는 것"이라고 생각합니다. 그래서 친구, 동료, 심지어 가족에게 물어봅니다:',-1),a("ul",null,[a("li",null,"내 이 아이디어 어때?"),a("li",null,"이런 제품이 있다면, 쓸 것 같아?"),a("li",null,"이 기능 꽤 괜찮지 않아?")],-1),a("p",null,"상대방도 보통 매우 고무적인 피드백을 줍니다:",-1),a("ul",null,[a("li",null,"꽤 좋은데"),a("li",null,"쓸모 있어 보여"),a("li",null,"한번 해 보면 좋을 것 같아")],-1),a("p",null,'문제는, 이런 대답이 보통 판단에 도움이 되지 않는다는 것입니다. 그것들은 예의, 지지, 또는 당장 기분을 상하게 하고 싶지 않은 자연스러운 반응에 더 가깝습니다. 자신이 "시장 검증"을 얻었다고 생각하지만, 사실은 판단에 사용하기 어려운 위안을 모았을 뿐입니다.',-1),a("p",null,[r("The Mom Test 방법론은 바로 이 문제를 해결하기 위해 만들어졌습니다. 이것은 우리에게 상기시킵니다: "),a("strong",null,"사용자가 일부러 거짓말을 하는 것이 아니라, 질문하는 방식 자체가 상대를 듣기 좋지만 쓸모없는 대답으로 자연스럽게 유도하고 있는 것입니다.")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">최소 SOP</p><p><strong>목적</strong>: 이 글을 읽은 후, 사용자와 어떻게 대화해야 &quot;꽤 좋아 보인다&quot;만 듣지 않고, 정말로 방향을 판단하는 데 도움이 되는 정보를 끌어낼 수 있는지 더 명확히 알게 됩니다.</p><p><strong>실행 항목</strong>: 원래 물어보려고 했던 5개의 질문을 바꾸고, &quot;최근에 언제 일어났는지&quot;, &quot;그때 어떻게 처리했는지&quot;를 우선으로 물어보세요.</p><p><strong>결과</strong>: 어떤 것이 의견이고, 어떤 것이 판단을 뒷받침할 수 있는 진짜 증거인지 더 쉽게 구분할 수 있게 됩니다.</p><p><strong>키워드 바로가기</strong>: <a href="#mom-what">The Mom Test란</a> · <a href="#mom-principles">세 가지 핵심 원칙</a> · <a href="#mom-ai">AI가 도와주는 방법</a></p></div><h2 id="배울-내용" tabindex="-1">배울 내용 <a class="header-anchor" href="#배울-내용" aria-label="Permalink to “배울 내용”">​</a></h2><ol><li>The Mom Test가 정확히 무엇을 해결하는지, 왜 많은 &quot;사용자 조사&quot;가 사실 실제 정보를 조사하지 못했는지</li><li>이 방법의 가장 핵심적인 몇 가지 원칙: 의견은 적게 묻고, 행동은 많이 묻기; 가정은 적게 묻고, 사실은 많이 묻기</li><li>가양성 피드백을 얻기 쉬운 질문을 어떻게 더 가치 있는 인터뷰 질문으로 바꾸는지</li><li>The Mom Test를 JTBD, 수요 검증, MVP 판단과 어떻게 연결해서 사용하는지</li></ol><p><a id="mom-what"></a></p><h2 id="_1-the-mom-test란-무엇인가" tabindex="-1"><a href="#top-mom">1. The Mom Test란 무엇인가</a> <a class="header-anchor" href="#_1-the-mom-test란-무엇인가" aria-label="Permalink to “1. The Mom Test란 무엇인가”">​</a></h2><p>The Mom Test는 Rob Fitzpatrick의 동명의 책에서 유래했습니다. 이름은 농담처럼 들리지만, 핵심은 매우 정확합니다:</p><p><strong>당신의 엄마조차도 &quot;이건 형편없는 아이디어야&quot;라고 직접 말하기 어렵습니다.</strong></p><p>그 이유는 그녀가 정직하지 않아서가 아니라:</p><ul><li>당신을 상처 주고 싶지 않아서</li><li>무의식적으로 당신을 응원하게 되어서</li><li>당신의 표현 방식에 따라 대답하기 쉬워서</li></ul><p>사실 엄마뿐만 아니라, 친구, 동료, 예전 동학, 심지어 많은 낯선 사람도 당신의 제품 아이디어 앞에서 비슷한 &quot;긍정적 피드백&quot;을 줍니다. 이것이 수요가 정말로 존재한다는 것을 의미하지는 않으며, 단지 당신이 질문을 누구나 당신의 대답에 맞춰주기 쉬운 형태로 만들었다는 것을 의미할 뿐입니다.</p><p>그래서 The Mom Test의 핵심은 결코 &quot;엄마에게 묻지 마라&quot;가 아니라:</p><p><strong>누구에게나 당신의 대답에 맞춰주게 만드는 방식으로 질문하지 마라.</strong></p><p>이 방법이 정말로 가르치고 싶은 것은, 대화를 통해 실제 수요에 더 가까운 정보를 얻는 방법이며, 자신을 기분 좋게 하는 댓글을 모으는 것이 아닙니다.</p><h2 id="_2-해결하려는-핵심-문제" tabindex="-1">2. 해결하려는 핵심 문제 <a class="header-anchor" href="#_2-해결하려는-핵심-문제" aria-label="Permalink to “2. 해결하려는 핵심 문제”">​</a></h2><p>The Mom Test가 주로 해결하는 것은 매우 흔한 인지적 착각입니다:</p><p><strong>예의상의 긍정적 피드백을 실제 수요로 착각하는 것.</strong></p><p>예를 들어 물어본다면:</p><ul><li>이 앱 아이디어 어때요?</li><li>AI가 이력서 써주는 도구를 만들면, 쓸 건가요?</li><li>이 기능 가치 있지 않나요?</li></ul><p>이런 질문들의 공통점은:</p><ul><li>모두 &quot;의견&quot;을 묻고 있음</li><li>모두 약간의 암시를 담고 있음</li><li>모두 아직 일어나지 않은 미래에 대해 이야기하고 있음</li></ul><p>&quot;의견&quot;과 &quot;미래 가정&quot;에 대한 대답은 보통 불안정합니다. 많은 사람이 자신의 흥미, 실행력, 미래의 구매 의향을 과대평가합니다.</p><p>그래서 The Mom Test는 상기시킵니다:</p><ul><li>다른 사람이 당신의 아이디어에 대한 평가를 너무 믿지 마세요</li><li>다른 사람의 미래 행동 예측을 너무 믿지 마세요</li><li>사용자가 이미 일으킨 실제 행동으로 최대한 되돌아가세요</li></ul><p>&quot;쓸 건가요?&quot;보다 &quot;저번에 이 일 어떻게 처리했어요?&quot;가 보통 진실에 더 가깝기 때문입니다.</p><p><a id="mom-principles"></a></p><h2 id="_3-세-가지-핵심-원칙" tabindex="-1"><a href="#top-mom">3. 세 가지 핵심 원칙</a> <a class="header-anchor" href="#_3-세-가지-핵심-원칙" aria-label="Permalink to “3. 세 가지 핵심 원칙”">​</a></h2><p>가장 중요한 부분만 먼저 기억하고 싶다면, 다음 세 가지 원칙을 먼저 기억하세요.</p><h3 id="_3-1-아이디어를-적게-이야기하고-사용자의-과거-실제-경험을-많이-이야기하기" tabindex="-1">3.1 아이디어를 적게 이야기하고, 사용자의 과거 실제 경험을 많이 이야기하기 <a class="header-anchor" href="#_3-1-아이디어를-적게-이야기하고-사용자의-과거-실제-경험을-많이-이야기하기" aria-label="Permalink to “3.1 아이디어를 적게 이야기하고, 사용자의 과거 실제 경험을 많이 이야기하기”">​</a></h3><p>많은 비효율적 인터뷰가 처음부터 자신의 솔루션을 설명하고, 자신이 얼마나 흥분했는지, 어떤 제품을 만들려고 하는지 이야기합니다. 문제는, 너무 많이 이야기하면 상대가 쉽게 &quot;협조하기&quot;, &quot;응원하기&quot; 상태로 전환된다는 것입니다.</p><p>반면, 더 나은 방법은 상대방의 경험에 초점을 맞추는 것입니다:</p><ul><li>최근에 이 문제를 만난 것이 언제였나요?</li><li>그때 무엇을 하고 있었나요?</li><li>마지막에 어떻게 처리했나요?</li><li>어느 단계가 가장 번거로웠나요?</li></ul><p>이런 질문이 대화를 자연스럽게 현실로 되돌리고, 상상 속의 선호에 머물지 않게 한다는 것을 발견할 것입니다.</p><h3 id="_3-2-추상적-의견은-적게-묻고-구체적-사실은-많이-묻기" tabindex="-1">3.2 추상적 의견은 적게 묻고, 구체적 사실은 많이 묻기 <a class="header-anchor" href="#_3-2-추상적-의견은-적게-묻고-구체적-사실은-많이-묻기" aria-label="Permalink to “3.2 추상적 의견은 적게 묻고, 구체적 사실은 많이 묻기”">​</a></h3><p>&quot;이 기능 꽤 좋은 것 같아&quot;, &quot;괜찮아 보여&quot;, &quot;좀 쓸모 있을 것 같아&quot; 같은 표현은 모두 너무 추상적이어서, 제품 의사결정을 지도하기 어렵습니다.</p><p>더 가치 있는 정보는 보통 이렇게 생겼습니다:</p><ul><li>저번 주에 이 일 때문에 2시간을 낭비했어요</li><li>지금 Excel과 위챗으로 버티고 있어요</li><li>지난달에 비슷한 도구에 이미 돈을 썼어요</li><li>제일 무서운 건 틀리는 거지, 느린 게 아니에요</li></ul><p>이것이 바로 문제의 강도, 빈도, 결제 가능성을 판단하는 데 정말로 도움이 되는 정보입니다.</p><h3 id="_3-3-사용자가-어떤-솔루션을-원하는지-적게-묻고-지금-어떻게-문제를-해결하는지-많이-보기" tabindex="-1">3.3 사용자가 어떤 솔루션을 원하는지 적게 묻고, 지금 어떻게 문제를 해결하는지 많이 보기 <a class="header-anchor" href="#_3-3-사용자가-어떤-솔루션을-원하는지-적게-묻고-지금-어떻게-문제를-해결하는지-많이-보기" aria-label="Permalink to “3.3 사용자가 어떤 솔루션을 원하는지 적게 묻고, 지금 어떻게 문제를 해결하는지 많이 보기”">​</a></h3><p>사용자는 자신의 고충을 설명하는 데 능숙하지만, 솔루션을 설계하는 데는 반드시 능숙하지는 않습니다.</p><p>물어본다면:</p><ul><li>AI가 이걸 자동으로 해주면 어떨까요?</li><li>스마트 기능을 추가하면 도움이 될까요?</li></ul><p>얻는 것은 보통 어떤 솔루션에 대한 모호한 태도일 뿐, 수요 자체는 아닙니다.</p><p>더 나은 질문은:</p><ul><li>지금 이 문제를 어떤 방법으로 처리하시나요?</li><li>왜 이 방식을 선택했나요?</li><li>어디가 충분히 좋지 않나요?</li></ul><p>기존 대체 솔루션을 파악하는 것이 &quot;무엇을 원하시나요&quot;를 직접 묻는 것보다 보통 더 중요합니다.</p><h2 id="_4-왜-사람들은-항상-듣기-좋지만-쓸모없는-대답을-줄까" tabindex="-1">4. 왜 사람들은 항상 듣기 좋지만 쓸모없는 대답을 줄까 <a class="header-anchor" href="#_4-왜-사람들은-항상-듣기-좋지만-쓸모없는-대답을-줄까" aria-label="Permalink to “4. 왜 사람들은 항상 듣기 좋지만 쓸모없는 대답을 줄까”">​</a></h2><p>이것을 이해하면, 인터뷰에서 오해가 많이 줄어듭니다.</p><h3 id="_4-1-사람은-무의식적으로-예의를-지킴" tabindex="-1">4.1 사람은 무의식적으로 예의를 지킴 <a class="header-anchor" href="#_4-1-사람은-무의식적으로-예의를-지킴" aria-label="Permalink to “4.1 사람은 무의식적으로 예의를 지킴”">​</a></h3><p>특히 대화 상대와 관계가 있을 때, 직접 말하기 어렵습니다:</p><ul><li>이 방향은 별로인 것 같아요</li><li>저 절대 안 써요</li><li>이 문제는 저한테 그렇게 중요하지 않아요</li></ul><p>대신 &quot;꽤 좋은데&quot;, &quot;기회가 되면 한번 해 봐요&quot;라고 말할 가능성이 높습니다.</p><h3 id="_4-2-사람은-미래의-자신을-과대평가함" tabindex="-1">4.2 사람은 미래의 자신을 과대평가함 <a class="header-anchor" href="#_4-2-사람은-미래의-자신을-과대평가함" aria-label="Permalink to “4.2 사람은 미래의 자신을 과대평가함”">​</a></h3><p>많은 사람이 진심으로 미래에 자신이 이렇게 할 것이라고 믿습니다:</p><ul><li>더 자제할 것</li><li>더 열심히 공부할 것</li><li>더 기꺼이 결제할 것</li><li>더 기꺼이 새로운 도구를 시도할 것</li></ul><p>그래서 &quot;있으면 쓸 것 같아요&quot;라는 말은, 종종 미래에 정말로 쓴다는 것과 같지 않습니다.</p><h3 id="_4-3-질문-방식-자체가-대답을-유도함" tabindex="-1">4.3 질문 방식 자체가 대답을 유도함 <a class="header-anchor" href="#_4-3-질문-방식-자체가-대답을-유도함" aria-label="Permalink to “4.3 질문 방식 자체가 대답을 유도함”">​</a></h3><p>물어본다면:</p><ul><li>내 이 아이디어 꽤 좋지 않아?</li><li>이 기능 당신에게 도움이 많이 되지 않아?</li></ul><p>사실 이미 &quot;정답&quot;을 몰래 질문에 넣은 것입니다.</p><p>이것이 The Mom Test가 특히 강조하는 이유입니다: <strong>인터뷰를 인정을 찾는 과정으로 만들지 마세요.</strong></p><h2 id="_5-직접-비교-어떤-질문이-망가지기-쉽고-어떤-질문이-더-가치-있는지" tabindex="-1">5. 직접 비교: 어떤 질문이 망가지기 쉽고, 어떤 질문이 더 가치 있는지 <a class="header-anchor" href="#_5-직접-비교-어떤-질문이-망가지기-쉽고-어떤-질문이-더-가치-있는지" aria-label="Permalink to “5. 직접 비교: 어떤 질문이 망가지기 쉽고, 어떤 질문이 더 가치 있는지”">​</a></h2><p>아래 비교는 거의 모든 초보자가 사용하는 것입니다.</p><table tabindex="0"><thead><tr><th>망가지기 쉬운 질문</th><th>더 가치 있는 질문</th></tr></thead><tbody><tr><td>내 이 아이디어 어때요?</td><td>최근에 이 문제를 만난 것이 언제였나요?</td></tr><tr><td>이 제품이 있으면 쓸 건가요?</td><td>지금 이 일을 어떻게 처리하고 계세요?</td></tr><tr><td>이 기능에 결제할 의향이 있나요?</td><td>저번에 이 문제 때문에 돈을 써본 적이 있나요? 무엇에 썼나요?</td></tr><tr><td>이 기능이 중요하다고 생각하시나요?</td><td>이 과정에서 가장 번거롭고, 가장 느리고, 가장 불안한 단계는 어디인가요?</td></tr><tr><td>AI가 자동으로 해주면 어떨까요?</td><td>지금 왜 더 편한 해결책을 아직 못 찾았나요?</td></tr></tbody></table><p>이 표에서 가장 중요한 것은 구체적인 문장이 아니라, 배후의 방향입니다:</p><ul><li>의견에서 사실로</li><li>미래에서 과거로</li><li>당신의 솔루션에서 사용자의 문제로</li></ul><h2 id="_6-제로-베이스도-바로-사용할-수-있는-인터뷰-리듬" tabindex="-1">6. 제로 베이스도 바로 사용할 수 있는 인터뷰 리듬 <a class="header-anchor" href="#_6-제로-베이스도-바로-사용할-수-있는-인터뷰-리듬" aria-label="Permalink to “6. 제로 베이스도 바로 사용할 수 있는 인터뷰 리듬”">​</a></h2><p>지금 당장 누군가와 이야기하러 가고 싶다면, 다음 순서대로 진행하세요.</p><h3 id="_6-1-시작-판매가-아니라-학습하고-있다고-설명" tabindex="-1">6.1 시작: 판매가 아니라 학습하고 있다고 설명 <a class="header-anchor" href="#_6-1-시작-판매가-아니라-학습하고-있다고-설명" aria-label="Permalink to “6.1 시작: 판매가 아니라 학습하고 있다고 설명”">​</a></h3><p>예를 들어:</p><blockquote><p>요즘 다들 이런 문제를 어떻게 처리하는지 연구하고 있어요. 실제 상황을 먼저 파악하고 싶어서, 뭔가 팔러 온 건 아니에요.</p></blockquote><p>이런 표현은 상대가 &quot;긍정적인 피드백을 줘야 해&quot;라는 심리적 부담을 더 쉽게 내려놓게 합니다.</p><h3 id="_6-2-최근-실제-경험에서-시작" tabindex="-1">6.2 최근 실제 경험에서 시작 <a class="header-anchor" href="#_6-2-최근-실제-경험에서-시작" aria-label="Permalink to “6.2 최근 실제 경험에서 시작”">​</a></h3><p>이런 질문으로 시작할 수 있습니다:</p><ul><li>최근에 이 문제를 만난 것이 언제였나요?</li><li>그때 무슨 일이 있었나요?</li><li>첫 반응은 어떻게 처리했나요?</li></ul><p>대화가 구체적인 사건으로 들어가면, 정보의 질이 보통 눈에 띄게 향상됩니다.</p><h3 id="_6-3-행동-비용-대체-솔루션을-계속-추적" tabindex="-1">6.3 행동, 비용, 대체 솔루션을 계속 추적 <a class="header-anchor" href="#_6-3-행동-비용-대체-솔루션을-계속-추적" aria-label="Permalink to “6.3 행동, 비용, 대체 솔루션을 계속 추적”">​</a></h3><p>계속 물어보세요:</p><ul><li>지금 어떤 방법으로 해결하고 계세요?</li><li>이 방법에서 가장 불편한 점은 무엇인가요?</li><li>이 일에 시간, 돈, 또는 에너지를 얼마나 썼나요?</li><li>다른 방법도 시도해 보셨나요? 왜 계속 사용하지 않았나요?</li></ul><h3 id="_6-4-마지막에-고통과-우선순위-판단" tabindex="-1">6.4 마지막에 고통과 우선순위 판단 <a class="header-anchor" href="#_6-4-마지막에-고통과-우선순위-판단" aria-label="Permalink to “6.4 마지막에 고통과 우선순위 판단”">​</a></h3><p>&quot;아픈지 아닌지&quot;를 직접 물어볼 필요 없이, 세부 사항에서 판단할 수 있습니다:</p><ul><li>자주 겪는 일인지</li><li>이미 스스로 해결책을 찾고 있는지</li><li>이미 비용을 지불할 의향이 있는지</li><li>이야기할 때 뚜렷한 감정이 담겨 있는지</li></ul><p>이 모든 것이 &quot;이게 당신의 페인포인트인가요?&quot; 한마디보다 더 유용합니다.</p><h2 id="_7-더-완전한-예시" tabindex="-1">7. 더 완전한 예시 <a class="header-anchor" href="#_7-더-완전한-예시" aria-label="Permalink to “7. 더 완전한 예시”">​</a></h2><p>&quot;AI로 대학생의 이력서를 수정하는&quot; 제품을 만들고 싶다고 가정해 봅시다.</p><h3 id="잘못된-질문" tabindex="-1">잘못된 질문 <a class="header-anchor" href="#잘못된-질문" aria-label="Permalink to “잘못된 질문”">​</a></h3><p>학우에게 물어봅니다:</p><blockquote><p>AI 이력서 최적화 도구를 만들고 싶은데, 어때요? 공고에 맞게 이력서를 자동으로 수정해 준다면, 쓸 건가요?</p></blockquote><p>이때 상대는 아마 이렇게 말할 것입니다:</p><ul><li>꽤 좋은 것 같아</li><li>쓸모 있을 것 같아</li></ul><blockquote><p>무료면 써 볼게</p></blockquote><p>이런 대답은 수요가 얼마나 강한지 판단하는 데 거의 도움이 되지 않습니다.</p><h3 id="더-나은-질문" tabindex="-1">더 나은 질문 <a class="header-anchor" href="#더-나은-질문" aria-label="Permalink to “더 나은 질문”">​</a></h3><p>이렇게 바꿀 수 있습니다:</p><blockquote><p>최근에 이력서 수정한 게 언제였어? 그때 왜 수정했어? 어떻게 수정했어? 어느 단계가 가장 막혔어? 다른 사람에게 검토를 부탁해 본 적 있어? 예전에 이력서 때문에 돈을 쓰거나 많은 시간을 쓴 적 있어?</p></blockquote><p>이런 질문을 통해 얻을 수 있는 정보는:</p><ul><li>많은 사람이 작성 방법을 모르는 것이 아니라, 다른 직무에 맞게 재작성하는 방법을 모른다는 것</li><li>가장 아픈 것이 레이아웃이 아니라, &quot;어떤 경험이 쓸 만한지 모르는 것&quot;이라는 것</li><li>그들이 미루는 것이 게을러서가 아니라, 매번 이력서를 수정하는 것이 너무 소모적이기 때문이라는 것</li><li>이미 선배 조언, 템플릿 웹사이트, AI 도구, 친구 검토로 간신히 해결하고 있다는 것</li></ul><p>이때, 진짜 문제에 훨씬 더 가까워집니다.</p><h2 id="_8-the-mom-test와-jtbd를-어떻게-함께-사용할까" tabindex="-1">8. The Mom Test와 JTBD를 어떻게 함께 사용할까 <a class="header-anchor" href="#_8-the-mom-test와-jtbd를-어떻게-함께-사용할까" aria-label="Permalink to “8. The Mom Test와 JTBD를 어떻게 함께 사용할까”">​</a></h2><p>JTBD가 &quot;사용자가 어떤 진전을 완수하고 싶은지&quot;를 명확히 보게 해준다면, The Mom Test는 다음을 가르치는 것에 더 가깝습니다:</p><p><strong>인터뷰를 통해 이 job이 정말로 존재하는지 확인하는 방법.</strong></p><p>두 가지를 연결해서 사용할 수 있습니다:</p><ol><li>먼저 JTBD로 job 하나를 가설로 세움</li><li>The Mom Test 방식으로 사용자에게 최근 실제 경험을 물어봄</li><li>이 job이 정말로 빈도가 높고, 실제이며, 우선적으로 할 가치가 있는지 확인</li></ol><p>예를 들어 JTBD 가설이 다음과 같다면:</p><blockquote><p>인턴십에 지원할 준비를 할 때, 기존 이력서를 공고에 맞는 버전으로 빠르게 수정하고 싶고, 최대한 빨리 지원을 완료하고 싶어.</p></blockquote><p>The Mom Test 스타일의 질문으로 검증할 수 있습니다:</p><ul><li>최근에 지원한 게 언제였어?</li><li>그때 이력서를 어떻게 수정했어?</li><li>어느 부분이 가장 쓰기 어려웠어?</li><li>수정한 후에 충분히 좋은지 어떻게 판단했어?</li></ul><p>이렇게 하면 방법이 연결됩니다:</p><ul><li>JTBD가 수요 가설을 정의하는 데 도움을 줌</li><li>The Mom Test가 인터뷰를 통해 가설을 검증하는 데 도움을 줌</li></ul><h2 id="_9-초보자가-사용자-인터뷰를-할-때-가장-흔한-오해" tabindex="-1">9. 초보자가 사용자 인터뷰를 할 때 가장 흔한 오해 <a class="header-anchor" href="#_9-초보자가-사용자-인터뷰를-할-때-가장-흔한-오해" aria-label="Permalink to “9. 초보자가 사용자 인터뷰를 할 때 가장 흔한 오해”">​</a></h2><h3 id="_9-1-인터뷰를-제품-소개회로-만듦" tabindex="-1">9.1 인터뷰를 제품 소개회로 만듦 <a class="header-anchor" href="#_9-1-인터뷰를-제품-소개회로-만듦" aria-label="Permalink to “9.1 인터뷰를 제품 소개회로 만듦”">​</a></h3><p>자신의 아이디어를 너무 많이 이야기하면, 상대가 실제 상황을 알려주는 대신 당신에게 협조하기 시작합니다.</p><h3 id="_9-2-인터뷰-대상이-모두-아는-사람" tabindex="-1">9.2 인터뷰 대상이 모두 아는 사람 <a class="header-anchor" href="#_9-2-인터뷰-대상이-모두-아는-사람" aria-label="Permalink to “9.2 인터뷰 대상이 모두 아는 사람”">​</a></h3><p>아는 사람과 대화하는 것이 나쁜 것은 아니지만, 아는 사람이 당신을 응원하기 더 쉽습니다. 최소한 지인 외에 실제 사용자에 더 가까운 사람들을 섞어야 하며, 자신을 지지하는 사람만 찾아서는 안 됩니다.</p><h3 id="_9-3-너무-일찍-기능을-추적하며-물어봄" tabindex="-1">9.3 너무 일찍 기능을 추적하며 물어봄 <a class="header-anchor" href="#_9-3-너무-일찍-기능을-추적하며-물어봄" aria-label="Permalink to “9.3 너무 일찍 기능을 추적하며 물어봄”">​</a></h3><p>문제를 아직 파악하지 못한 상태에서 버튼, 인터페이스, 기능 세부 사항을 추적하면, 보통 너무 일찍 솔루션 단계에 진입한 것입니다.</p><h3 id="_9-4-쓸게요-한마디를-검증-결과로-받아들임" tabindex="-1">9.4 &quot;쓸게요&quot; 한마디를 검증 결과로 받아들임 <a class="header-anchor" href="#_9-4-쓸게요-한마디를-검증-결과로-받아들임" aria-label="Permalink to “9.4 &quot;쓸게요&quot; 한마디를 검증 결과로 받아들임”">​</a></h3><p>인터뷰는 방향을 판단하는 데 도움을 줄 수 있지만, 검증이 완료된 것과 같지 않습니다. 진짜 검증은 결국 사용자가 실제 비용(시간, 전환 비용, 체험 행동, 심지어 결제)을 지불할 의향이 있는지에 달려 있습니다.</p><h3 id="_9-5-인터뷰-후-정리하지-않음" tabindex="-1">9.5 인터뷰 후 정리하지 않음 <a class="header-anchor" href="#_9-5-인터뷰-후-정리하지-않음" aria-label="Permalink to “9.5 인터뷰 후 정리하지 않음”">​</a></h3><p>대화가 끝나면 정보가 빠르게 모호한 인상으로 변합니다. 최대한 빨리 정리하는 것이 좋습니다:</p><ul><li>빈도가 높은 문제</li><li>사용자가 한 말 속의 감정 단어</li><li>현재 대체 솔루션</li><li>이미 지불한 비용</li><li>자신의 새로운 판단</li></ul><h2 id="_10-바로-복사해서-사용할-수-있는-질문-목록" tabindex="-1">10. 바로 복사해서 사용할 수 있는 질문 목록 <a class="header-anchor" href="#_10-바로-복사해서-사용할-수-있는-질문-목록" aria-label="Permalink to “10. 바로 복사해서 사용할 수 있는 질문 목록”">​</a></h2><p>빠르게 시작하고 싶다면, 여기에 충분히 범용적인 질문 세트가 있습니다.</p><h3 id="시작-질문" tabindex="-1">시작 질문 <a class="header-anchor" href="#시작-질문" aria-label="Permalink to “시작 질문”">​</a></h3><ul><li>최근에 이 문제를 만난 것이 언제였나요?</li><li>그때 구체적으로 무슨 일이 있었나요?</li></ul><h3 id="행동-질문" tabindex="-1">행동 질문 <a class="header-anchor" href="#행동-질문" aria-label="Permalink to “행동 질문”">​</a></h3><ul><li>그때 어떻게 처리했나요?</li><li>왜 이 방식을 선택했나요?</li></ul><h3 id="비용-질문" tabindex="-1">비용 질문 <a class="header-anchor" href="#비용-질문" aria-label="Permalink to “비용 질문”">​</a></h3><ul><li>이 일에 보통 시간이나 에너지를 얼마나 쓰나요?</li><li>해결하기 위해 돈을 써본 적이 있나요?</li></ul><h3 id="대체-솔루션-질문" tabindex="-1">대체 솔루션 질문 <a class="header-anchor" href="#대체-솔루션-질문" aria-label="Permalink to “대체 솔루션 질문”">​</a></h3><ul><li>다른 도구나 방법을 시도해 보셨나요?</li><li>왜 계속 사용하지 않았나요?</li></ul><h3 id="마무리-질문" tabindex="-1">마무리 질문 <a class="header-anchor" href="#마무리-질문" aria-label="Permalink to “마무리 질문”">​</a></h3><ul><li>앞으로 같은 문제를 다시 만나면, 가장 이상적인 해결 방식은 어떤 것일까요?</li></ul><p>주의: 이 마무리 질문은 물어볼 수 있지만, 뒤에 두는 것이 좋습니다. 왜냐하면 앞에서는 사실을 먼저 얻어야 하고, 소원은 나중에 얻어도 되기 때문입니다.</p><h2 id="_11-요약" tabindex="-1">11. 요약 <a class="header-anchor" href="#_11-요약" aria-label="Permalink to “11. 요약”">​</a></h2><p>The Mom Test의 가장 중요한 기여는 &quot;더 잘 채팅하는&quot; 기술을 주는 것이 아니라, 더 명확한 판단 방식을 구축하도록 돕는 것입니다:</p><ul><li>다른 사람이 당신의 아이디어를 칭찬하는 것을 너무 빨리 믿지 마세요</li><li>&quot;있으면 쓸게요&quot;를 실제 수요로 받아들이지 마세요</li><li>인터뷰를 인정을 찾는 과정으로 만들지 마세요</li></ul><p>진짜 가치 있는 인터뷰는, 최대한 다음 것들로 되돌아가야 합니다:</p><ul><li>사용자의 최근 실제 경험</li><li>지금 어떻게 처리하는지</li><li>이미 어떤 비용을 지불했는지</li><li>어느 부분에서 분명히 불편해하는지</li></ul><p>이런 식으로 물어보기 시작하면, 얻는 정보가 때때로 듣기에 그리 좋지 않을 수 있지만, 보통 더 유용합니다. 제품을 만들 때, <strong>유용한 진실은 항상 듣기 좋은 응원보다 더 중요합니다.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-ai를-활용해-사용자-인터뷰-하는-방법" tabindex="-1"><a href="#top-mom">12. AI를 활용해 사용자 인터뷰 하는 방법</a> <a class="header-anchor" href="#_12-ai를-활용해-사용자-인터뷰-하는-방법" aria-label="Permalink to “12. AI를 활용해 사용자 인터뷰 하는 방법”">​</a></h2><p>The Mom Test는 본질적으로 &quot;실제 사람과 대화하는&quot; 방법이므로, AI가 실제 인터뷰를 대체할 수는 없습니다. 하지만 AI는 인터뷰 전, 중, 후에 보조 역할을 하기에 매우 적합하며, 특히 초보자의 진입 장벽을 낮추는 데 도움이 됩니다.</p><h3 id="_12-1-ai로-망가지기-쉬운-질문을-재작성" tabindex="-1">12.1 AI로 &quot;망가지기 쉬운&quot; 질문을 재작성 <a class="header-anchor" href="#_12-1-ai로-망가지기-쉬운-질문을-재작성" aria-label="Permalink to “12.1 AI로 &quot;망가지기 쉬운&quot; 질문을 재작성”">​</a></h3><p>&quot;내 이 아이디어 어때요?&quot;라고 물으면 안 된다는 것을 알면서도, 입을 열면 여전히 이런 문장으로 돌아가는 사람이 많습니다. 준비한 질문을 먼저 AI에게 전달하여 재작성하도록 할 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>다음은 사용자 인터뷰를 준비하면서 물어보려는 질문입니다:</span></span>
<span class="line"><span>[질문 붙여넣기]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The Mom Test의 원칙으로 재작성해 주세요:</span></span>
<span class="line"><span>1. 의견형 질문은 삭제</span></span>
<span class="line"><span>2. 미래 가정 질문은 삭제</span></span>
<span class="line"><span>3. 과거 실제 행동, 기존 대체 솔루션, 이미 지불한 비용을 중심으로 한 질문으로 수정</span></span>
<span class="line"><span>4. 마지막으로 바로 인터뷰에 사용할 수 있는 8~10개의 질문 목록으로 정리</span></span></code></pre></div><p>아주 초보적인 입력도 가능합니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>사용자에게 물어보고 싶은데:</span></span>
<span class="line"><span>1. AI 이력서 수정 도구를 만들면 어때요?</span></span>
<span class="line"><span>2. 쓸 건가요?</span></span>
<span class="line"><span>3. 결제할 의향이 있나요?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>더 나은 질문으로 바꿔 주세요.</span></span></code></pre></div><p>AI의 유용한 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>재작성된 질문:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 최근에 이력서를 수정한 게 언제였나요?</span></span>
<span class="line"><span>2. 그때 왜 수정했나요?</span></span>
<span class="line"><span>3. 어떻게 수정했나요?</span></span>
<span class="line"><span>4. 어느 단계가 가장 시간이 많이 걸렸나요?</span></span>
<span class="line"><span>5. 다른 사람에게 검토를 부탁해 본 적이 있나요?</span></span>
<span class="line"><span>6. 예전에 이력서 수정 때문에 돈을 쓰거나 많은 시간을 쓴 적이 있나요?</span></span></code></pre></div><p>이런 출력은 매우 도움이 됩니다. 왜냐하면 &quot;의견을 묻는&quot; 질문을 &quot;실제 행동을 묻는&quot; 질문으로 직접 바꿔주기 때문입니다.</p><h3 id="_12-2-ai로-다른-대상을-위한-인터뷰-가이드라인-생성" tabindex="-1">12.2 AI로 다른 대상을 위한 인터뷰 가이드라인 생성 <a class="header-anchor" href="#_12-2-ai로-다른-대상을-위한-인터뷰-가이드라인-생성" aria-label="Permalink to “12.2 AI로 다른 대상을 위한 인터뷰 가이드라인 생성”">​</a></h3><p>같은 방향이라도, 다른 사용자군에게는 인터뷰 초점이 다릅니다. 예를 들어 학생, HR, 프리랜서의 관심사는 완전히 다릅니다. AI에게 다른 대상별로 각각 한 버전의 가이드라인을 작성하도록 할 수 있습니다:</p><ul><li>초보 사용자에게는 최근 실제 경험에 초점</li><li>헤비 사용자에게는 대체 솔루션과 고통에 초점</li><li>유료 사용자에게는 이미 비용을 지불했는지에 초점</li></ul><p>이렇게 하면 실제 대화에서 리듬감이 더 좋아지며, 모든 사람에게 같은 질문을 반복하지 않게 됩니다.</p><p>예를 들어 이렇게 입력할 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>두 가지 유형의 사람과 대화할 거예요:</span></span>
<span class="line"><span>1. 처음으로 인턴십을 찾는 대학생</span></span>
<span class="line"><span>2. 다른 사람의 이력서를 많이 검토해 본 선배</span></span>
<span class="line"><span></span></span>
<span class="line"><span>각각 6개의 인터뷰 가이드라인을 작성해 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>대학생 대상:</span></span>
<span class="line"><span>1. 최근에 인턴십에 지원한 게 언제였나요?</span></span>
<span class="line"><span>2. 그때 가장 막혔던 단계는 어디였나요?</span></span>
<span class="line"><span>3. 이력서가 제출 가능한지 어떻게 알았나요?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>선배 대상:</span></span>
<span class="line"><span>1. 최근에 다른 사람의 이력서를 검토해 준 게 언제였나요?</span></span>
<span class="line"><span>2. 가장 자주 보이는 명백한 문제는 무엇인가요?</span></span>
<span class="line"><span>3. 후배들이 가장 많이 막히는 단계는 어디인가요?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>이렇게 하면 제로에서 직접 질문을 구성할 필요 없이, 인터뷰 준비가 훨씬 수월해집니다.</p><h3 id="_12-3-ai로-인터뷰-기록-정리" tabindex="-1">12.3 AI로 인터뷰 기록 정리 <a class="header-anchor" href="#_12-3-ai로-인터뷰-기록-정리" aria-label="Permalink to “12.3 AI로 인터뷰 기록 정리”">​</a></h3><p>인터뷰가 끝난 후, 가장 흔히 발생하는 문제는 &quot;정보가 없는 것&quot;이 아니라 &quot;정보가 너무 흩어져 있는 것&quot;입니다. AI는 파편화된 대화를 구조화된 노트로 정리하는 데 매우 적합합니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>다음은 3명의 사용자와의 인터뷰 기록입니다.</span></span>
<span class="line"><span>The Mom Test 관점으로 정리해 주세요:</span></span>
<span class="line"><span>1. 어떤 내용이 사실이고, 어떤 것이 의견인지</span></span>
<span class="line"><span>2. 사용자의 최근 실제 행동은 무엇인지</span></span>
<span class="line"><span>3. 현재 대체 솔루션은 무엇인지</span></span>
<span class="line"><span>4. 사용자가 이미 지불한 시간, 돈, 에너지 비용은 무엇인지</span></span>
<span class="line"><span>5. 어떤 문제가 반복적으로 언급되었는지</span></span>
<span class="line"><span>6. 어떤 말이 긍정적으로 들리지만 증거가 부족한지</span></span></code></pre></div><p>이 단계는 특히 가치가 있습니다. 왜냐하면 &quot;꽤 좋아 보이는&quot; 내용과 &quot;정말로 판단을 뒷받침할 수 있는&quot; 내용을 분리하는 데 도움이 되기 때문입니다.</p><p>간단한 입력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>한 사용자와 대화한 기록입니다:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 도구가 있으면 한번 써 볼 것 같다고 했어요</span></span>
<span class="line"><span>- 지난주에 이력서 수정하느라 하루 종일 걸렸다고 했어요</span></span>
<span class="line"><span>- 지금은 주로 친구에게 검토를 부탁한다고 했어요</span></span>
<span class="line"><span>- 제일 어려운 건 어디까지 수정해야 제출할 수 있는지 모르는 거라고 했어요</span></span>
<span class="line"><span></span></span>
<span class="line"><span>의견과 사실을 나눠 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>의견:</span></span>
<span class="line"><span>- 도구가 있으면 한번 써 볼 것 같다</span></span>
<span class="line"><span></span></span>
<span class="line"><span>사실:</span></span>
<span class="line"><span>- 지난주에 이력서 수정에 하루 종일 걸림</span></span>
<span class="line"><span>- 현재 대체 솔루션은 친구에게 검토 부탁</span></span>
<span class="line"><span>- 가장 어려운 점은 언제 &quot;제출 가능&quot;한지 모르는 것</span></span>
<span class="line"><span></span></span>
<span class="line"><span>수요 판단에 활용할 수 있는 핵심:</span></span>
<span class="line"><span>- 이 문제는 최근에 실제로 발생함</span></span>
<span class="line"><span>- 사용자가 이미 상당한 시간 비용을 지불함</span></span>
<span class="line"><span>- 현재 솔루션은 타인에게 의존하여 불안정함</span></span></code></pre></div><p>이런 출력은 초보자에게 직관적으로 알려 줍니다: 어떤 말은 판단에 사용할 수 있고, 어떤 말은 그저 들어두면 되는지.</p><h3 id="_12-4-ai로-먼저-가벼운-온라인-검색-대행" tabindex="-1">12.4 AI로 먼저 가벼운 온라인 검색 대행 <a class="header-anchor" href="#_12-4-ai로-먼저-가벼운-온라인-검색-대행" aria-label="Permalink to “12.4 AI로 먼저 가벼운 온라인 검색 대행”">​</a></h3><p>아직 인터뷰를 시작하지 않았다면, AI에게 먼저 가벼운 외부 조사를 맡길 수 있습니다. 예를 들어:</p><ul><li>공개 커뮤니티에서, 사람들이 최근에 이 문제를 어떻게 불만 제기하는지</li><li>기존 도구에서 가장 많이 불만이 나오는 것이 무엇인지</li><li>사용자가 비슷한 문제에 이미 돈을 지불했는지</li><li>시장에 어떤 대체 솔루션이 이미 존재하는지</li></ul><p>이런 정보는 실제 인터뷰를 대체할 수 없지만, 더 빨리 상태에 진입하여 어디서 질문을 시작해야 할지 알 수 있게 해줍니다.</p><p>간단한 입력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>조사해 주세요:</span></span>
<span class="line"><span>&quot;대학생이 이력서를 수정할 때 가장 많이 불만을 제기하는 것&quot;</span></span>
<span class="line"><span>가장 흔한 불만 5가지를 아주 일상적인 말로 정리해 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>흔한 불만:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 이력서에 뭘 써야 할지 모름</span></span>
<span class="line"><span>2. 공고마다 수정해야 해서 너무 힘듦</span></span>
<span class="line"><span>3. 여러 버전을 수정했는데 여전히 충분히 좋은지 모르겠음</span></span>
<span class="line"><span>4. 신뢰할 수 있는 피드백을 줄 사람이 없음</span></span>
<span class="line"><span>5. 항상 준비가 안 된 것 같아서 계속 미룸</span></span></code></pre></div><p>이런 결과의 가치는, 인터뷰 진입점을 더 쉽게 찾을 수 있게 해준다는 것입니다.</p><h3 id="_12-5-ai를-인터뷰-복기-코치-로-활용" tabindex="-1">12.5 AI를 &quot;인터뷰 복기 코치&quot;로 활용 <a class="header-anchor" href="#_12-5-ai를-인터뷰-복기-코치-로-활용" aria-label="Permalink to “12.5 AI를 &quot;인터뷰 복기 코치&quot;로 활용”">​</a></h3><p>방금 끝난 인터뷰 기록을 AI에게 전달하여, 비판을 맡길 수도 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>다음은 제 사용자 인터뷰 기록입니다.</span></span>
<span class="line"><span>The Mom Test 관점에서 복기해 주세요:</span></span>
<span class="line"><span>1. 어떤 질문이 인정을 찾는 것에 너무 가까웠는지</span></span>
<span class="line"><span>2. 어떤 질문에 명백한 유도가 있었는지</span></span>
<span class="line"><span>3. 어디서 사실을 계속 추적할 수 있었는지</span></span>
<span class="line"><span>4. 다시 한번 한다면, 이 대화를 어떻게 더 잘 물어볼 수 있는지</span></span></code></pre></div><p>이것은 초보자에게 특히 도움이 됩니다. 왜냐하면 &quot;내가 증거를 수집하고 있는지, 아니면 응원을 수집하고 있는지&quot;에 대한 감각을 더 빨리 구축할 수 있기 때문입니다.</p><h2 id="📚-과제" tabindex="-1">📚 과제 <a class="header-anchor" href="#📚-과제" aria-label="Permalink to “📚 과제”">​</a></h2><p>위 내용을 바탕으로 다음 과제를 완성해 주세요:</p><ol><li>최근에 만들고 싶은 제품 방향을 하나 골라, 원래 물어볼 &quot;망가지기 쉬운&quot; 질문 5개를 먼저 작성하세요</li><li>이 5개의 질문을 The Mom Test 스타일에 더 부합하는 질문으로 재작성하세요</li><li>잠재 사용자 3명을 찾아, 적어도 한 번은 &quot;최근에 이 문제를 만난 것이 언제였나요&quot;라고 물어보세요</li><li>인터뷰가 끝난 후 4가지 정보를 정리하세요: 실제 행동, 대체 솔루션, 이미 지불한 비용, 반복적으로 등장한 어려움</li></ol><h2 id="더-읽어볼-만한-자료" tabindex="-1">더 읽어볼 만한 자료 <a class="header-anchor" href="#더-읽어볼-만한-자료" aria-label="Permalink to “더 읽어볼 만한 자료”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test 공식 웹사이트</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,186))])}}});export{k as __pageData,m as default};
